import{_ as n,a as t}from"./chunks/ugso_whatsapp_action.CCiayXGK.js";import{_ as r,o as i,c as a,a3 as l}from"./chunks/framework.BlfGB29P.js";const s="/assets/callmebot/de.png",o="/assets/callmebot/profiles-de.png",k=JSON.parse('{"title":"CallMeBot Whatsapp","description":"WhatsApp-Textnachrichten aus Home Assistant mit Empfängerprofilen und Blockly.","frontmatter":{"title":"CallMeBot Whatsapp","description":"WhatsApp-Textnachrichten aus Home Assistant mit Empfängerprofilen und Blockly."},"headers":[],"relativePath":"projects/callmebot/index.md","filePath":"projects/callmebot/index.md","lastUpdated":1792861021000}'),d={name:"projects/callmebot/index.md"};function h(c,e,u,p,g,m){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="callmebot-whatsapp" tabindex="-1">CallMeBot Whatsapp <a class="header-anchor" href="#callmebot-whatsapp" aria-label="Permalink to &quot;CallMeBot Whatsapp&quot;">​</a></h1><p>Seit 0.1.5 heißt die App <strong>CallMeBot Whatsapp</strong>. Bestehende Profile, MQTT-Themen und Entitäts-IDs bleiben erhalten. Die separate <a href="./../callmebot-signal/">CallMeBot Signal</a> verwendet eigene Profile und Schlüssel.</p><p>Beta <strong>HA-App 0.1.6</strong> im <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">gemeinsamen Repository mit Blocks for HA</a>. Oberfläche und Bausteine sind vollständig in <strong>DE/EN/FR</strong>, mit Systemsprache und Hell/Dunkel/System. Inspiration: <a href="https://github.com/ioBroker/ioBroker.whatsapp-cmb" target="_blank" rel="noreferrer">ioBroker.whatsapp-cmb</a>; eigenständige UGSo-Implementierung ohne ioBroker.</p><p><strong>Korrektur 0.1.1:</strong> Der Versandbutton funktioniert auch ohne <code>crypto.randomUUID</code>, etwa bei HTTP-Ingress. Nach dem Update die App neu starten und die Seite neu laden. Anfrage-IDs verwenden verfügbare Zufallsbytes oder einen Zeitstempel mit Zähler; sie dienen der Dublettenprüfung, nicht der Anmeldung.</p><p><img src="'+s+'" alt="CallMeBot-Oberfläche auf Deutsch"></p><h2 id="installieren-und-einrichten" tabindex="-1">Installieren und einrichten <a class="header-anchor" href="#installieren-und-einrichten" aria-label="Permalink to &quot;Installieren und einrichten&quot;">​</a></h2><ol><li>Das Repository <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> im HA-App-Store hinzufügen.</li><li><strong>CallMeBot Whatsapp</strong> installieren, MQTT-Broker einrichten und App starten.</li><li>Oberfläche über HA-Ingress öffnen. Der interne MQTT-Dienst liefert bevorzugt die Broker-Zugangsdaten; die App-Optionen sind der Fallback.</li><li>Mit der aktuellen Bot-Nummer aus der <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">offiziellen Aktivierungsanleitung</a> den eigenen Empfänger aktivieren. Genau <code>I allow callmebot to send me messages</code> an den Bot senden.</li><li>Profil-ID, Name, eigene aktivierte Telefonnummer <strong>mit + und Ländervorwahl</strong> sowie passenden API-Schlüssel speichern. Standardprofil festlegen. Bis zu 16 Profile.</li><li>Die Testschaltfläche sendet wirklich an das ausgewählte gespeicherte Profil; bei leerer Auswahl an den Standardempfänger.</li></ol><p>Ein leeres Schlüsselfeld beim Speichern behält den vorhandenen Schlüssel. Die Oberfläche erhält den Schlüssel niemals zurück. Er liegt in <code>/data/profiles.json</code>, nicht in Blockly, MQTT-Nachrichten, Browser-Speicher oder Protokollen. Die Backend-Datei ist nicht verschlüsselt und wird in HA-Sicherungen aufgenommen.</p><h2 id="blockly-callmebot" tabindex="-1">Blockly: CallMeBot <a class="header-anchor" href="#blockly-callmebot" aria-label="Permalink to &quot;Blockly: CallMeBot&quot;">​</a></h2><h3 id="gespeicherte-profile-auswahlen" tabindex="-1">Gespeicherte Profile auswählen <a class="header-anchor" href="#gespeicherte-profile-auswahlen" aria-label="Permalink to &quot;Gespeicherte Profile auswählen&quot;">​</a></h3><p>Ab <strong>CallMeBot 0.1.2 und Blocks for HA 0.1.69</strong> öffnet das Profilfeld eine durchsuchbare Auswahl mit Profilnamen, Profil-ID und Standardempfänger. <strong>Neu laden</strong> aktualisiert die Liste. Im Block steht der Profilname, im Projekt und YAML bleibt die unveränderte ID gespeichert. Eine leere ID verwendet den aktuellen Standardempfänger.</p><p><img src="'+o+'" alt="CallMeBot-Profilauswahl auf Deutsch"></p><p>Beide Apps aktualisieren und neu starten, dann die Blocks-Seite neu laden. HA muss mit dem MQTT-Broker verbunden sein und MQTT-Discovery mit dem Standardpräfix <code>homeassistant</code> erlauben. CallMeBot veröffentlicht einen Diagnose-Sensor, standardmäßig <code>sensor.ugso_callmebot_profiles</code>, über den Blocks den Katalog mit seiner vorhandenen HA-Verbindung liest. Eine Umbenennung des Sensors ist möglich; er wird anhand seiner Katalog-Kennung gefunden. Technische Grundlage: <a href="https://www.home-assistant.io/integrations/sensor.mqtt/" target="_blank" rel="noreferrer">HA MQTT-Sensoren und JSON-Attribute</a>.</p><p>Der retained Katalog <code>ugso/callmebot/profiles</code> enthält nur IDs, Namen, Standardprofil, Anzahl und Kennung. Telefonnummern, Nachrichten und API-Schlüssel werden nicht veröffentlicht. Änderungen und MQTT-Neuverbindungen aktualisieren den Katalog. Profilnamen sind in MQTT und HA sichtbar.</p><p>Wenn App, MQTT, Discovery oder HA-Verbindung fehlen, bleiben manuelle Profil-ID und Standardempfänger nutzbar. Gelöschte IDs werden im Projekt nicht automatisch ersetzt; die App lehnt einen Versand an ein fehlendes Profil ab.</p><p>Seit <strong>Blocks for HA 0.1.68</strong> unter <strong>Nachrichten → WhatsApp · CallMeBot</strong>.</p><p><img src="'+n+'" alt="CallMeBot-Block"></p><p>Profil-ID angeben oder leer lassen für das Standardprofil. Text, Variable oder Jinja als Nachricht anschließen. Protokollstufe: nur Fehler, keins oder Info. Der Block erzeugt eine native <code>mqtt.publish</code>-Aktion. JSON wird erst nach der Template-Auswertung serialisiert; Anführungszeichen und Zeilenumbrüche bleiben korrekt.</p><p>HA muss MQTT eingerichtet haben. JSON-Projekte erhalten den Komfortblock. Beim YAML-Import bleibt der Versand als allgemeine HA-/MQTT-Aktion erhalten.</p><h2 id="alternative-vorhandene-whatsapp-integration" tabindex="-1">Alternative: vorhandene WhatsApp-Integration <a class="header-anchor" href="#alternative-vorhandene-whatsapp-integration" aria-label="Permalink to &quot;Alternative: vorhandene WhatsApp-Integration&quot;">​</a></h2><p><img src="'+t+'" alt="WhatsApp-Integrationsblock"></p><p>Der zweite Block ruft die <a href="https://faserf.github.io/ha-whatsapp/services.html" target="_blank" rel="noreferrer">WhatsApp-Integration von FaserF</a> direkt auf. Deren App-URL und <strong>API-Token aus der WhatsApp-App</strong> einmal im HA-Einrichtungsdialog hinterlegen. Der Block benötigt diesen Token nicht; die Integration verwaltet ihn.</p><p>Auswahl: <code>whatsapp.send_message · number</code> für das ältere Format, <code>whatsapp.send_message · target</code> für die aktuelle Doku oder <code>notify.whatsapp</code>, wenn diese Aktion eingerichtet ist. Empfänger <strong>mit Ländervorwahl ohne +</strong>, Nachricht als Text/Jinja. Optionales Konto wird nur bei <code>whatsapp.send_message</code> ausgegeben. Passende YAML-Aktionen werden als Komfortblock importiert; zusätzliche Optionen bleiben in der allgemeinen HA-Aktion.</p><p>Diese Variante benötigt keine CallMeBot-App und keinen CallMeBot-Schlüssel. Installation und WhatsApp-Verbindung übernimmt die vorhandene Integration.</p><h2 id="mqtt-protokoll-und-grenzen" tabindex="-1">MQTT-Protokoll und Grenzen <a class="header-anchor" href="#mqtt-protokoll-und-grenzen" aria-label="Permalink to &quot;MQTT-Protokoll und Grenzen&quot;">​</a></h2><ul><li>Versand: <code>ugso/callmebot/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Nutzdaten: <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Hallo aus HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Leeres/fehlendes Profil nutzt den Standardempfänger.</li><li>Optional: <code>request_id</code> für eine Stunde Dublettenprüfung je Profil, maximal 1000 gespeicherte IDs.</li><li>Ergebnis: <code>ugso/callmebot/result</code>, nicht retained, nur Profil, Anfrage-ID, Status und Zeit; keine Nachricht oder Schlüssel.</li><li>Verfügbarkeit: <code>ugso/callmebot/availability</code>, retained <code>online</code>/<code>offline</code>, zeigt die Broker-Verbindung.</li><li>Maximal 4000 Zeichen, Warteschlange 20, mindestens 10 Sekunden zwischen Versandversuchen je Profil. Schnellere Befehle werden abgelehnt, nicht verzögert.</li><li>Keine automatischen Wiederholungen oder Wiedergabe nach Neustart. Retained-Versandbefehle werden abgelehnt.</li><li>Ein MQTT-Namensraum und eine Client-ID: eine App-Instanz pro Broker. Schreibrechte für Versandbefehle im Broker beschränken. Der interne Broker bleibt Standard; externe MQTT-Verbindungen mit geprüftem TLS sind optional.</li></ul><p>CallMeBot Free ist für persönliche Texte an eigene aktivierte Nummern gedacht. Keine Gruppen, Medien, Antworten oder Zustellbestätigung. <code>accepted</code> bestätigt nur die API-Annahme. Telefonnummer, Schlüssel und Text gehen per HTTPS an CallMeBot. Quelle: <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">CallMeBot-Aktivierung und API</a>.</p><h2 id="entwicklungsstand" tabindex="-1">Entwicklungsstand <a class="header-anchor" href="#entwicklungsstand" aria-label="Permalink to &quot;Entwicklungsstand&quot;">​</a></h2><p>Docker-Build und Start, Backend-Tests mit Mock-Anbieter, MQTT-Protokoll, DE/EN/FR-Oberfläche, mobile Ansicht und Blockly-Export sind geprüft. Echte WhatsApp-Zustellung und Installation unter HA-Supervisor müssen mit der eigenen Einrichtung geprüft werden. Es wurden keine realen Nachrichten verschickt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">Quellcode und lokale Testbefehle</a> · Apache-2.0 · Unabhängiges Community-Projekt.</p><h2 id="beta-historie-profilsicherung-und-mqtt-tls" tabindex="-1">Beta: Historie, Profilsicherung und MQTT-TLS <a class="header-anchor" href="#beta-historie-profilsicherung-und-mqtt-tls" aria-label="Permalink to &quot;Beta: Historie, Profilsicherung und MQTT-TLS&quot;">​</a></h2><p>Die Historie enthält bis zu 200 dauerhaft gespeicherte Einträge mit Zeitpunkt, Profil-ID, Quelle und Ergebnis. Filter nach Profil oder Fehlerstatus und bestätigtes Löschen sind verfügbar. Nachrichten, Telefonnummern, API-Schlüssel und Anfrage-IDs werden nicht in der Historie gespeichert. „Angenommen“ bestätigt weiterhin nur die Annahme durch CallMeBot, keine Zustellung. Bei Speicherfehlern wird der Versand nicht wiederholt.</p><p>Die Profilsicherung verschlüsselt Profile einschließlich Telefonnummern, API-Schlüsseln und Standardempfänger mit AES-GCM und einem aus dem Sicherungspasswort abgeleiteten Schlüssel (scrypt). Mindestens 12 Zeichen; Passwort separat aufbewahren. Es wird nicht gespeichert. Ohne Passwort ist keine Wiederherstellung möglich. Wiederherstellen ersetzt die Profile erst nach Bestätigung und erfolgreicher Prüfung; falsches Passwort, beschädigte Dateien oder Sicherungen der anderen CallMeBot-App ändern nichts. Bei wartenden Versandversuchen wird die Wiederherstellung abgewiesen. MQTT-Zugangsdaten und Historie sind nicht enthalten; für diese weiterhin die vollständige HA-App-Sicherung verwenden.</p><p>Unter MQTT-Verbindung bleibt „HA-Broker automatisch verwenden“ der bisherige Standard. Für einen externen Broker die Automatik deaktivieren und Host, Port, Benutzer und Passwort angeben. TLS prüft Zertifikat und Hostname; eigene CA und Client-Zertifikat/Schlüssel sind als PEM-Datei oder Text möglich. TLS-Port passend wählen, häufig 8883. Leere Geheimnisfelder behalten gespeicherte Werte. HA/Blocks müssen diesen Broker verwenden oder die Send-/Result-/Profil-/Discovery-Topics zwischen den Brokern weiterleiten; eine externe Verbindung allein ersetzt keine Broker-Bridge.</p><p>Bestehende profiles.json, Profile, Schlüssel, MQTT-Themen und Entitäts-IDs bleiben erhalten. Neue Historie: /data/history.json; ausdrücklich gespeicherte MQTT-Einstellungen: /data/mqtt.json. Die Konfiguration wird beim Update nicht automatisch umgeschrieben. Alle neuen Oberflächentexte sind DE/EN/FR.</p><p>Die Oberfläche und Beschreibung heißen Beta. Home Assistant unterstützt keinen nativen stage-Wert beta; der gültige technische Status experimental bleibt deshalb bestehen. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA-Konfiguration</a>.</p>',36)])])}const A=r(d,[["render",h]]);export{k as __pageData,A as default};
